    /**
     * Method to retrieve the Item via an ItemPrimaryKey.
     * @param 	id Long
     * @return 	Item
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Item handle( FindItemQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getItemId() );
    }
    
    /**
     * Method to retrieve a collection of all Items
     *
     * @param	query	FindAllItemQuery 
     * @return 	List<Item> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Item> handle( FindAllItemQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindItem,
 * but only if the id matches
 *
 * @param		entity	Item
 */
	protected void emitFindItem( Item entity ) {
		LOGGER.info("handling emitFindItem" );
		
	    queryUpdateEmitter.emit(FindItemQuery.class,
	                            query -> query.getFilter().getItemId().equals(entity.getItemId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllItem
	 * 
	 * @param		entity	Item
	 */
	protected void emitFindAllItem( Item entity ) {
		LOGGER.info("handling emitFindAllItem" );
		
	    queryUpdateEmitter.emit(FindAllItemQuery.class,
	                            query -> true,
	                            entity);
	}

